/*
[演算法邏輯說明]
判斷字串 s 是否為字串 t 的子序列 (Subsequence)。
1. 使用貪婪演算法 (Greedy Algorithm)。
2. 維護兩個指針，一個指向 s 的開頭，一個指向 t 的開頭。
3. 遍歷 t 的每一個字元。如果當前 t 的字元與 s 指針指向的字元相同，則將 s 的指針向後移動一格。
4. 如果 s 的指針最終能移動到 s 的末尾之後，則說明 s 是 t 的子序列，輸出 "Yes"；否則輸出 "No"。
*/

#include <iostream>
#include <string>

using namespace std;

int main() {
    string s, t;
    while (cin >> s >> t) {
        int i = 0, j = 0;
        while (i < s.length() && j < t.length()) {
            if (s[i] == t[j]) {
                i++;
            }
            j++;
        }
        if (i == s.length()) {
            cout << "Yes" << endl;
        } else {
            cout << "No" << endl;
        }
    }
    return 0;
}

